# Specify Normaliser
class Normalizer(object):
    """Normalize a Tensor column by column and restore it later. """

    def __init__(self, tensor):
        """tensor is taken as a sample to calculate the mean and std"""
        self.mean = torch.mean(tensor, dim=0)
        self.std = torch.std(tensor, dim=0)

    def norm(self, tensor):
        return (tensor - self.mean) / self.std

    def denorm(self, normed_tensor):
        return normed_tensor * self.std + self.mean

    def state_dict(self):
        return {'mean': self.mean,
                'std': self.std}

    def load_state_dict(self, state_dict):
        self.mean = state_dict['mean']
        self.std = state_dict['std']

# Create surogate model architecture for Regression tasks
class surogateModel(nn.Module):
    def __init__(self, input_size, hidden_size, output_size):
        super(surogateModel, self).__init__()

        self.conv_to_fc_softplus = nn.Softplus()
        self.conv_to_fc = nn.Linear(input_size, hidden_size)
        self.conv_to_fct = nn.Linear(hidden_size, input_size)
        self.fc_out = nn.Linear(hidden_size, output_size)
        self.fc_outt = nn.Linear(output_size, hidden_size)
    def forward(self, crys_fea):
        try:
          crys_fea = self.conv_to_fc(self.conv_to_fc_softplus(crys_fea))
        except:
           crys_fea = self.conv_to_fct(self.conv_to_fc_softplus(crys_fea))
        crys_fea = self.conv_to_fc_softplus(crys_fea)
        try:
          out = self.fc_out(crys_fea)
        except:
          out = self.fc_outt(crys_fea)
        return out

class surogateModel2(nn.Module):
    def __init__(self):
        super(surogateModel2, self).__init__()

        self.model = nn.Sequential(
            nn.Softplus(),
            nn.Linear(69, 128),
            nn.Softplus(),
            nn.Linear(128, 2)
        )

    def forward(self, crys_fea):
        out = self.model(crys_fea)
        return out

class CustomModel(nn.Module):
    def __init__(self, weight1, bias1, weight2, bias2):
        super(CustomModel, self).__init__()
        self.weight1 = weight1
        self.bias1 = bias1
        self.weight2 = weight2
        self.bias2 = bias2

    def softplus(self, x, beta=1, threshold=20):
        return torch.where(x * beta > threshold, x, torch.log1p(torch.exp(beta * x)) / beta)

    def forward(self, x):
        x = self.softplus(x)
        x = torch.matmul(x, self.weight1.t()) + self.bias1
        x = self.softplus(x)
        x = torch.matmul(x, self.weight2.t()) + self.bias2
        return x
